parameters.text:
=Procesa la información del siguiente cliente en mora y envía su mensaje de cobro individual usando la herramienta:

- Nombre: {{ $json.nombre }}
- Teléfono: {{ $json.telefono }}
- Detalle de la cuenta: {{ $json.mensaje_original }}  

IMPORTANTE:
Que la redaccinon del mensaje no sea la misma que varie para que no me clasifique como span.  pero si debe de mantener el nombre de cada cliente

parameters.jsCode:
// 1. Obtener la respuesta del nodo 'cartera de credito'
const response = $input.first().json;

// 2. Extraer el arreglo 'data' que contiene la lista de clientes
const clientes = response.data || [];

const outputItems = [];

// 3. Recorrer cada registro de la cartera
for (const cliente of clientes) {
  const numeroTelefono = cliente.phoneNumber ? cliente.phoneNumber.toString().trim() : "";

  // Limpiar el nombre (si está vacío o tiene solo espacios, usar un valor por defecto)
  let nombreCliente = cliente.firstName ? cliente.firstName.trim() : "";
  if (!nombreCliente) {
    nombreCliente = "Cliente";
  }

  // Filtrar que exista un número de teléfono válido
  if (numeroTelefono) {
    outputItems.push({
      json: {
        nombre: nombreCliente,
        telefono: numeroTelefono,
        mensaje_original: cliente.mensaje || "",
        url_imagen: cliente.urlImage || ""
      }
    });
  }
}

// 4. Retornar los elementos preparados para el Loop Over Items
// Nota: Usa .slice(0, 2) mientras haces pruebas para que solo procese los primeros 2 registros
return outputItems.slice(0, 2);
